def create_table(dynamodb):
    print(f"Creating table '{TABLE_NAME}'...")
    table = dynamodb.create_table(
        TableName=TABLE_NAME,
        KeySchema=[
            {"AttributeName": "identifier", "KeyType": "HASH"}
        ],
        AttributeDefinitions=[
            {"AttributeName": "identifier", "AttributeType": "S"}
        ],
        BillingMode="PAY_PER_REQUEST"
    )
    print(f"Waiting for table to become active...")
    table.wait_until_exists()
    print(f"Table '{TABLE_NAME}' is active.")
    return table


def populate_table(table):
    print(f"Populating table with {len(MAPPINGS)} mappings...")
    with table.batch_writer() as batch:
        for identifier, output_folder_name in MAPPINGS:
            batch.put_item(Item={
                "identifier": identifier,
                "output_folder_name": output_folder_name
            })
    print("Done.")


def main():
    aws_profile = os.getenv("AWS_PROFILE")
    if aws_profile:
        print(f"Using AWS profile: {aws_profile}")
    else:
        print("WARNING: AWS_PROFILE not set, using default profile")
    session = boto3.Session(profile_name=aws_profile, region_name=REGION)
    dynamodb = session.resource("dynamodb")

    # Check if table already exists
    existing_tables = [t.name for t in dynamodb.tables.all()]
    if TABLE_NAME in existing_tables:
        print(f"Table '{TABLE_NAME}' already exists. Loading existing table.")
        table = dynamodb.Table(TABLE_NAME)
    else:
        table = create_table(dynamodb)

    populate_table(table)
    print(f"\nAll {len(MAPPINGS)} identifier prefix mappings loaded into '{TABLE_NAME}'.")


if __name__ == "__main__":
    main()
